import re
from datetime import datetime, timedelta

# Define severity levels and date ranges
severity_levels = ['ERROR', 'WARNING', 'INFO']
date_ranges = {
    'today': (datetime(2025, 8, 12), datetime(2025, 8, 12)),
    'last_7_days': (datetime(2025, 8, 6), datetime(2025, 8, 12)),
    'last_30_days': (datetime(2025, 7, 13), datetime(2025, 8, 12)),
    'month_to_date': (datetime(2025, 8, 1), datetime(2025, 8, 12)),
    'total': (None, None)
}

# Initialize count dictionary
count = {period: {severity: 0 for severity in severity_levels} for period in date_ranges}

# Function to parse log lines
def parse_log_line(line):
    match = re.match(r'( ERROR | WARNING | INFO ) ', line)
    if match:
        return match.group(1)
    return None

# Function to check if a date is within a range
def is_within_range(date, start, end):
    if start is None and end is None:
        return True
    if start is None:
        return date <= end
    if end is None:
        return date >= start
    return start <= date <= end

# Process each log file
for filename in os.listdir('/app/logs'):
    if filename.endswith('.log'):
        date_str, source = filename.split('_', 1)
        date = datetime.strptime(date_str, '%Y-%m-%d')
        with open(os.path.join('/app/logs', filename), 'r') as file:
            for line in file:
                severity = parse_log_line(line)
                if severity in severity_levels:
                    for period, (start, end) in date_ranges.items():
                        if is_within_range(date, start, end):
                            count[period][severity] += 1

# Write the results to summary.csv
with open('/app/summary.csv', 'w') as file:
    file.write('period,severity,count
')
    for period, severity_counts in count.items():
        for severity, count in severity_counts.items():
            file.write(f'{period},{severity},{count}
')"
}

